Here is the commit message:
drm/amdkfd: make sure VM is ready for updating operations
MIME-Version: 1.0
Content-Type: text/plain; charset=UTF-8
Content-Transfer-Encoding: 8bit

When page table BOs were evicted but not validated before
updating page tables, VM is still in evicting state,
amdgpu_vm_update_range returns -EBUSY and
restore_process_worker runs into a dead loop.

v2: Split the BO validation and page table update into two
separate loops in amdgpu_amdkfd_restore_process_bos. (Felix)
  1.Validate BOs
  2.Validate VM (and DMABuf attachments)
  3.Update page tables for the BOs validated above

Fixes: 50661eb1a2c8 ("drm/amdgpu: Auto-validate DMABuf imports in compute VMs")
Signed-off-by: Lang Yu <Lang.Yu@amd.com>
Acked-by: Christian König <christian.koenig@amd.com>
Reviewed-by: Felix Kuehling <felix.kuehling@amd.com>
Signed-off-by: Alex Deucher <alexander.deucher@amd.com>

Here is the root cause:
The bug occurs when page table buffer objects (BOs) are evicted but not validated before updating the page tables. This results in the virtual memory (VM) being in an evicting state, causing the `amdgpu_vm_update_range` function to return -EBUSY, which leads to the `restore_process_worker` entering a dead loop.

Here is the patch:
  */
 int amdgpu_amdkfd_gpuvm_restore_process_bos(void *info, struct dma_fence __rcu **ef)
 {
 	struct amdkfd_process_info *process_info = info;
 	struct amdgpu_vm *peer_vm;
 	struct kgd_mem *mem;
 	struct list_head duplicate_save;
 	struct amdgpu_sync sync_obj;
 	unsigned long failed_size = 0;
 	unsigned long total_size = 0;
 	struct drm_exec exec;
 	int ret;

 	INIT_LIST_HEAD(&duplicate_save);

 	mutex_lock(&process_info->lock);

 	drm_exec_init(&exec, DRM_EXEC_IGNORE_DUPLICATES, 0);
 	drm_exec_until_all_locked(&exec) {
 		list_for_each_entry(peer_vm, &process_info->vm_list_head,
 				    vm_list_node) {
 			ret = amdgpu_vm_lock_pd(peer_vm, &exec, 2);
 			drm_exec_retry_on_contention(&exec);
 			if (unlikely(ret)) {
 				pr_err("Locking VM PD failed, ret: %d\n", ret);
 				goto ttm_reserve_fail;
 			}
 		}

 		/* Reserve all BOs and page tables/directory. Add all BOs from
 		 * kfd_bo_list to ctx.list
 		 */
 		list_for_each_entry(mem, &process_info->kfd_bo_list,
 				    validate_list) {
 			struct drm_gem_object *gobj;

 			gobj = &mem->bo->tbo.base;
 			ret = drm_exec_prepare_obj(&exec, gobj, 1);
 			drm_exec_retry_on_contention(&exec);
 			if (unlikely(ret)) {
 				pr_err("drm_exec_prepare_obj failed, ret: %d\n", ret);
 				goto ttm_reserve_fail;
 			}
 		}
 	}

 	amdgpu_sync_create(&sync_obj);

-	/* Validate BOs and map them to GPUVM (update VM page tables). */
+	/* Validate BOs managed by KFD */
 	list_for_each_entry(mem, &process_info->kfd_bo_list,
 			    validate_list) {

 		struct amdgpu_bo *bo = mem->bo;
 		uint32_t domain = mem->domain;
-		struct kfd_mem_attachment *attachment;
 		struct dma_resv_iter cursor;
 		struct dma_fence *fence;

 		total_size += amdgpu_bo_size(bo);

 		ret = amdgpu_amdkfd_bo_validate(bo, domain, false);
 		if (ret) {
 			pr_debug("Memory eviction: Validate BOs failed\n");
 			failed_size += amdgpu_bo_size(bo);
 			ret = amdgpu_amdkfd_bo_validate(bo,
 						AMDGPU_GEM_DOMAIN_GTT, false);
 			if (ret) {
 				pr_debug("Memory eviction: Try again\n");
 				goto validate_map_fail;
 			}
 		}
 		dma_resv_for_each_fence(&cursor, bo->tbo.base.resv,
 					DMA_RESV_USAGE_KERNEL, fence) {
 			ret = amdgpu_sync_fence(&sync_obj, fence);
 			if (ret) {
 				pr_debug("Memory eviction: Sync BO fence failed. Try again\n");
 				goto validate_map_fail;
 			}
 		}
+	}
+
+	if (failed_size)
+		pr_debug("0x%lx/0x%lx in system\n", failed_size, total_size);
+
+	/* Validate PDs, PTs and evicted DMABuf imports last. Otherwise BO
+	 * validations above would invalidate DMABuf imports again.
+	 */
+	ret = process_validate_vms(process_info, &exec.ticket);
+	if (ret) {
+		pr_debug("Validating VMs failed, ret: %d\n", ret);
+		goto validate_map_fail;
+	}
+
+	/* Update mappings managed by KFD. */
+	list_for_each_entry(mem, &process_info->kfd_bo_list,
+			    validate_list) {
+		struct kfd_mem_attachment *attachment;
+
 		list_for_each_entry(attachment, &mem->attachments, list) {
 			if (!attachment->is_mapped)
 				continue;

 			if (attachment->bo_va->base.bo->tbo.pin_count)
 				continue;

 			kfd_mem_dmaunmap_attachment(mem, attachment);
 			ret = update_gpuvm_pte(mem, attachment, &sync_obj);
 			if (ret) {
 				pr_debug("Memory eviction: update PTE failed. Try again\n");
 				goto validate_map_fail;
 			}
 		}
 	}

-	if (failed_size)
-		pr_debug("0x%lx/0x%lx in system\n", failed_size, total_size);
-
-	/* Validate PDs, PTs and evicted DMABuf imports last. Otherwise BO
-	 * validations above would invalidate DMABuf imports again.
-	 */
-	ret = process_validate_vms(process_info, &exec.ticket);
-	if (ret) {
-		pr_debug("Validating VMs failed, ret: %d\n", ret);
-		goto validate_map_fail;
-	}
-
 	/* Update mappings not managed by KFD */
 	list_for_each_entry(peer_vm, &process_info->vm_list_head,
 			vm_list_node) {
 		struct amdgpu_device *adev = amdgpu_ttm_adev(
 			peer_vm->root.bo->tbo.bdev);

 		ret = amdgpu_vm_handle_moved(adev, peer_vm, &exec.ticket);
 		if (ret) {
 			pr_debug("Memory eviction: handle moved failed. Try again\n");
 			goto validate_map_fail;
 		}
 	}

 	/* Update page directories */
 	ret = process_update_pds(process_info, &sync_obj);
 	if (ret) {
 		pr_debug("Memory eviction: update PDs failed. Try again\n");
 		goto validate_map_fail;
 	}

 	/* Sync with fences on all the page tables. They implicitly depend on any
 	 * move fences from amdgpu_vm_handle_moved above.
 	 */
 	ret = process_sync_pds_resv(process_info, &sync_obj);
 	if (ret) {
 		pr_debug("Memory eviction: Failed to sync to PD BO moving fence. Try again\n");
 		goto validate_map_fail;
 	}

 	/* Wait for validate and PT updates to finish */
 	amdgpu_sync_wait(&sync_obj, false);

 	/* The old eviction fence may be unsignaled if restore happens
 	 * after a GPU reset or suspend/resume. Keep the old fence in that
 	 * case. Otherwise release the old eviction fence and create new
 	 * one, because fence only goes from unsignaled to signaled once
 	 * and cannot be reused. Use context and mm from the old fence.
 	 *
 	 * If an old eviction fence signals after this check, that's OK.
 	 * Anyone signaling an eviction fence must stop the queues first
 	 * and schedule another restore worker.
 	 */
 	if (dma_fence_is_signaled(&process_info->eviction_fence->base)) {
 		struct amdgpu_amdkfd_fence *new_fence =
 			amdgpu_amdkfd_fence_create(
 				process_info->eviction_fence->base.context,
 				process_info->eviction_fence->mm,
 				NULL);

 		if (!new_fence) {
 			pr_err("Failed to create eviction fence\n");
 			ret = -ENOMEM;
 			goto validate_map_fail;
 		}
 		dma_fence_put(&process_info->eviction_fence->base);
 		process_info->eviction_fence = new_fence;
 		replace_eviction_fence(ef, dma_fence_get(&new_fence->base));
 	} else {
 		WARN_ONCE(*ef != &process_info->eviction_fence->base,
 			  "KFD eviction fence doesn't match KGD process_info");
 	}

 	/* Attach new eviction fence to all BOs except pinned ones */
 	list_for_each_entry(mem, &process_info->kfd_bo_list, validate_list) {
 		if (mem->bo->tbo.pin_count)
 			continue;

 		dma_resv_add_fence(mem->bo->tbo.base.resv,
 				   &process_info->eviction_fence->base,
 				   DMA_RESV_USAGE_BOOKKEEP);
 	}
 	/* Attach eviction fence to PD / PT BOs and DMABuf imports */
 	list_for_each_entry(peer_vm, &process_info->vm_list_head,
 			    vm_list_node) {
 		struct amdgpu_bo *bo = peer_vm->root.bo;

 		dma_resv_add_fence(bo->tbo.base.resv,
 				   &process_info->eviction_fence->base,
 				   DMA_RESV_USAGE_BOOKKEEP);
 	}

 validate_map_fail:
 	amdgpu_sync_free(&sync_obj);
 ttm_reserve_fail:
 	drm_exec_fini(&exec);
 	mutex_unlock(&process_info->lock);
 	return ret;
 }



